mapper.select:
SELECT MAIN.ACISKYSAKICD , MAIN.ACISKYSAKINMN , MAIN.ACIURI , MAIN.ACISHIME , MAIN.APAPKIHONCD , MAIN.APSHOPCD , MAIN.APSKYSAKICD , MAIN.SHIMEPRCSJISSIDD , MAIN.KONKAIURIKIN , MAIN.APTOKUISAKICNT , AP_MST.APNM , SP_MST.SHOPNM , SYKM1.MOJISETTEIATAI AS TEL1 , SP_MST.RENRAKUSAKINON1 AS TELNO1 , SYKM1.MOJISETTEIATAI AS TEL2 , SP_MST.RENRAKUSAKINON2 AS TELNO2 , SYKM1.MOJISETTEIATAI AS TEL3 , SP_MST.RENRAKUSAKINON3 AS TELNO3 FROM ( SELECT BASE.SKYSAKICD AS ACISKYSAKICD , BASE.SKYSAKINMN1 AS ACISKYSAKINMN , DECODE(SUM(BASE.ACIURI), 0, '0', '1') AS ACIURI , DECODE(SUM(BASE.ACISHIME), 0, '0', '1') AS ACISHIME , BASE.APAPKIHONCD , BASE.APSHOPCD , BASE.APSKYSAKICD , MAX(BASE.SHIMEPRCSJISSIDD) AS SHIMEPRCSJISSIDD , SUM(BASE.KONKAIURIKIN) AS KONKAIURIKIN , COUNT(*) AS APTOKUISAKICNT FROM ( SELECT TKMST.SKYSAKICD , TKMST.SKYSAKINMN1 , ( SELECT COUNT(*) FROM S07W007T NAURI_WK INNER JOIN S06T001T URI_TBL_ACI ON ( NAURI_WK.ACIAPKIHONCD = URI_TBL_ACI.APKIHONCD AND NAURI_WK.ACISHOPCD = URI_TBL_ACI.SHOPCD AND NAURI_WK.URIDNPYNO = URI_TBL_ACI.URIDNPYNO AND URI_TBL_ACI.YUKOKBN = '1' AND URI_TBL_ACI.SKYPRCSJISSIDD = '00000000' AND NAURI_WK.SHIMEDYDM = SUBSTR(#{ shimedydm1, jdbcType = VARCHAR }, 0, 6) ) WHERE NAURI_WK.ACIAPKIHONCD = NA_MST.ACIAPKIHONCD AND NAURI_WK.ACISHOPCD = NA_MST.ACISHOPCD AND NAURI_WK.APAPKIHONCD = NA_MST.APAPKIHONCD AND NAURI_WK.APSHOPCD = NA_MST.APSHOPCD AND NAURI_WK.APTOKUISAKICD = NA_MST.APTOKUISAKICD ) AS ACIURI , ( SELECT COUNT(*) FROM S07T001T ACI_SKZ WHERE ACI_SKZ.APKIHONCD = NA_MST.ACIAPKIHONCD AND ACI_SKZ.SHOPCD = NA_MST.ACISHOPCD AND ACI_SKZ.SKYSAKICD = TKMST.SKYSAKICD AND ACI_SKZ.TOKUISAKICD = NA_MST.ACITOKUISAKICD AND ACI_SKZ.YUKOKBN = '1' AND ACI_SKZ.SKYPRCSJISSIKBN = '1' AND ACI_SKZ.SHIMEDYDM = SUBSTR(#{ shimedydm1, jdbcType = VARCHAR }, 0, 6) AND ACI_SKZ.SHIMEDD = #{shimeddforbalance,jdbcType=VARCHAR} ) AS ACISHIME , ( SELECT MAX(SHIMEPRCSJISSIDD) FROM S07T001T SKZ_TBL WHERE SKZ_TBL.YUKOKBN = '1' AND SKZ_TBL.SKYPRCSJISSIKBN = '1' AND SKZ_TBL.SHIMEDYDM = SUBSTR(#{ shimedydm1, jdbcType = VARCHAR }, 0, 6) AND NA_MST.APAPKIHONCD = SKZ_TBL.APKIHONCD AND NA_MST.APSHOPCD = SKZ_TBL.SHOPCD AND NA_MST.APTOKUISAKICD = SKZ_TBL.TOKUISAKICD AND NA_MST.APSKYSAKICD = SKZ_TBL.SKYSAKICD ) AS SHIMEPRCSJISSIDD , ( SELECT SUM( NVL(SKZ_TBL.KONKAITAXNUKIURIKIN, 0) + NVL(SKZ_TBL.KONKAISHOHITAXKIN, 0) ) FROM S07T001T SKZ_TBL WHERE SKZ_TBL.YUKOKBN = '1' AND SKZ_TBL.SKYPRCSJISSIKBN = '1' AND SKZ_TBL.SHIMEDYDM = SUBSTR(#{ shimedydm1, jdbcType = VARCHAR }, 0, 6) AND NA_MST.APAPKIHONCD = SKZ_TBL.APKIHONCD AND NA_MST.APSHOPCD = SKZ_TBL.SHOPCD AND NA_MST.APTOKUISAKICD = SKZ_TBL.TOKUISAKICD AND NA_MST.APSKYSAKICD = SKZ_TBL.SKYSAKICD ) AS KONKAIURIKIN , NA_MST.APAPKIHONCD , NA_MST.APSHOPCD , NA_MST.APSKYSAKICD FROM S02M057T NA_MST INNER JOIN ( SELECT TK_MST.APKIHONCD , TK_MST.SHOPCD , TK_MST.TOKUISAKICD , TK_MST.SKYSAKICD , SK_MST.SKYSAKINMN1 FROM S02M013T TK_MST INNER JOIN S02M017T SK_MST ON ( TK_MST.APKIHONCD = SK_MST.APKIHONCD AND TK_MST.SHOPCD = SK_MST.SHOPCD AND TK_MST.SKYSAKICD = SK_MST.SKYSAKICD AND SK_MST.SKYSHIMEDD = #{ shimedd, jdbcType = VARCHAR }
AND SK_MST.SKYSAKICD = #{ skysakicd, jdbcType = VARCHAR }
) ) TKMST ON ( TKMST.APKIHONCD = NA_MST.ACIAPKIHONCD AND TKMST.SHOPCD = NA_MST.ACISHOPCD AND TKMST.TOKUISAKICD = NA_MST.ACITOKUISAKICD ) WHERE NA_MST.YUKOKBN = '1' AND NA_MST.ACIAPKIHONCD = #{ apkihoncd, jdbcType = VARCHAR } AND NA_MST.ACISHOPCD = #{ shopcd, jdbcType = VARCHAR } AND EXISTS ( SELECT 1 FROM S02M017T SK_MST WHERE SK_MST.APKIHONCD = NA_MST.APAPKIHONCD AND SK_MST.SHOPCD = NA_MST.APSHOPCD AND SK_MST.SKYSAKICD = NA_MST.APSKYSAKICD AND SK_MST.ACIKEIYUFLG = '1' ) AND NOT EXISTS ( SELECT 1 FROM S02M013T APTK_MST WHERE APTK_MST.APKIHONCD = NA_MST.APAPKIHONCD AND APTK_MST.SHOPCD = NA_MST.APSHOPCD AND APTK_MST.TOKUISAKICD = NA_MST.APTOKUISAKICD AND (APTK_MST.TOKUISAKIJOTAI, APTK_MST.JOTAISTS) IN (('2', '02'), ('4', '06'), ('6', '10')) AND 0 = ( SELECT COUNT(1) FROM S06T001T URI_TBL_AP WHERE URI_TBL_AP.APKIHONCD = NA_MST.APAPKIHONCD AND URI_TBL_AP.SHOPCD = NA_MST.APSHOPCD AND URI_TBL_AP.TOKUISAKICD = NA_MST.APTOKUISAKICD AND URI_TBL_AP.SKYSAKICD = NA_MST.APSKYSAKICD AND URI_TBL_AP.SKYSHIMEDYDM = SUBSTR(#{ shimedydm1, jdbcType = VARCHAR }, 0, 6) ) ) ) BASE
WHERE BASE.SHIMEPRCSJISSIDD IS NOT NULL
WHERE BASE.SHIMEPRCSJISSIDD IS NULL
GROUP BY BASE.SKYSAKICD , BASE.SKYSAKINMN1 , BASE.APAPKIHONCD , BASE.APSHOPCD , BASE.APSKYSAKICD ) MAIN INNER JOIN S02M001T AP_MST ON (MAIN.APAPKIHONCD = AP_MST.APKIHONCD) INNER JOIN S02M046T SP_MST ON ( MAIN.APAPKIHONCD = SP_MST.APKIHONCD AND MAIN.APSHOPCD = SP_MST.SHOPCD ) LEFT JOIN S02M006T SYKM1 ON ( SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.SETTEINO = '011' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEICD = SP_MST.RENRAKUSAKINOKBNN1 ) LEFT JOIN S02M006T SYKM2 ON ( SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.SETTEINO = '011' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEICD = SP_MST.RENRAKUSAKINOKBNN2 ) LEFT JOIN S02M006T SYKM3 ON ( SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.SETTEINO = '011' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEICD = SP_MST.RENRAKUSAKINOKBNN3 ) ORDER BY MAIN.ACISKYSAKICD , MAIN.APAPKIHONCD , MAIN.APSHOPCD , MAIN.APSKYSAKICD
